// AlertManager posts {alerts:[{status,labels,annotations,startsAt,...}]}.
// Emit one item per FIRING alert; resolved ones are dropped upstream by
// send_resolved:false but re-checked here so a manual test can't slip past.
const root = $input.first().json;
const body = root.body ?? root;
const alerts = body.alerts ?? [];
const base = 'https://kubernetes.default.svc';

return alerts
  .filter(a => (a.status ?? 'firing') === 'firing')
  .map(a => {
    const l = a.labels ?? {};
    const ann = a.annotations ?? {};
    const ns = l.namespace || '';
    const pod = l.pod || '';
    const container = l.container || '';
    const hasPod = Boolean(ns && pod);
    const nsPath = ns ? base + '/api/v1/namespaces/' + ns : null;

    // /version is a tiny always-valid response used as a no-op target so
    // alerts without a pod/namespace still flow through the same chain
    // instead of needing a branch. Build prompt ignores it.
    const noop = base + '/version';
    const logQ = 'tailLines=80&timestamps=true' + (container ? '&container=' + container : '');

    return { json: {
      alertname:    l.alertname || 'unknown',
      severity:     l.severity || 'unknown',
      namespace:    ns,
      pod:          pod,
      container:    container,
      hasPod:       hasPod,
      labels:       l,
      summary:      ann.summary || '',
      description:  ann.description || '',
      runbook:      ann.runbook_url || '',
      startsAt:     a.startsAt || '',
      urlPod:       hasPod ? nsPath + '/pods/' + pod : noop,
      // Filter events to the alerting object when we know it; a bare
      // namespace-wide limit=25 buries the relevant rows under unrelated ones.
      urlEvents:    hasPod ? nsPath + '/events?fieldSelector=involvedObject.name=' + pod + '&limit=25'
                    : (ns ? nsPath + '/events?limit=25' : noop),
      urlLogs:      hasPod ? nsPath + '/pods/' + pod + '/log?' + logQ : noop,
    }};
  });

// Runs once per alert. Assembles whatever evidence actually came back;
// every fetch above is continue-on-fail, so missing data is normal and
// must be reported as missing rather than silently omitted.
const a = $('Fan out alerts').item.json;
const grab = (fn, fb) => { try { const v = fn(); return (v === undefined || v === null) ? fb : v; } catch (e) { return fb; } };

let podInfo = 'n/a (alert carries no pod label)';
if (a.hasPod) {
  const p = grab(() => $('Pod status').item.json, null);
  if (p && p.status) {
    const cs = (p.status.containerStatuses || []).map(c => {
      const state = Object.keys(c.state || {})[0] || 'unknown';
      const detail = JSON.stringify((c.state || {})[state] || {});
      return `  ${c.name}: ready=${c.ready} restarts=${c.restartCount} state=${state} ${detail}`;
    }).join('\n') || '  (none reported)';
    const conds = (p.status.conditions || [])
      .map(c => `${c.type}=${c.status}${c.reason ? '(' + c.reason + ')' : ''}`).join(' ');
    podInfo = [
      `phase=${p.status.phase}`,
      `node=${grab(() => p.spec.nodeName, '?')}`,
      `conditions: ${conds}`,
      'containers:',
      cs,
    ].join('\n');
  } else {
    podInfo = 'pod fetch failed or the pod no longer exists';
  }
}

let events = 'none returned';
const ev = grab(() => $('Events').item.json, null);
if (ev && Array.isArray(ev.items) && ev.items.length) {
  events = ev.items.slice(-15).map(e =>
    `${e.lastTimestamp || e.eventTime || ''} ${e.type} ${e.reason} ${grab(() => e.involvedObject.name, '')}: ${e.message}`
  ).join('\n');
}

let logs = 'none returned';
if (a.hasPod) {
  const lg = grab(() => $('Logs').item.json, null);
  const txt = typeof lg === 'string' ? lg : grab(() => lg.data, '') || grab(() => lg.body, '');
  if (typeof txt === 'string' && txt.trim()) {
    logs = txt.trim().split('\n').slice(-60).join('\n');
  }
}

const user = [
  `ALERT: ${a.alertname}  (severity=${a.severity})`,
  `SUMMARY: ${a.summary}`,
  `DESCRIPTION: ${a.description}`,
  `LABELS: ${JSON.stringify(a.labels)}`,
  `FIRING SINCE: ${a.startsAt}`,
  '',
  '--- POD STATUS ---',
  podInfo,
  '',
  '--- RECENT EVENTS ---',
  events,
  '',
  '--- RECENT LOGS ---',
  logs,
].join('\n').slice(0, 24000);

return { json: {
  user,
  alertname: a.alertname,
  severity:  a.severity,
  namespace: a.namespace,
  pod:       a.pod,
  runbook:   a.runbook,
}};

// Parse the fixed reply shape into a Discord message. The verdict is
// hoisted into the first line so it is readable from a notification
// preview without opening the channel -- that is the entire point.
const a = $('Build prompt').item.json;
const reply = ($json.choices && $json.choices[0] && $json.choices[0].message
  ? $json.choices[0].message.content : '' ).trim();

if (!reply) {
  return { json: { message: `❔ **TRIAGE FAILED** — \`${a.alertname}\`\nModel returned no content; falling back to the raw alert.`, verdict: 'UNKNOWN' } };
}

const m = reply.match(/VERDICT:\s*(ACT|WATCH|IGNORE)/i);
const verdict = m ? m[1].toUpperCase() : 'UNKNOWN';
const emoji = { ACT: '🔴', WATCH: '🟡', IGNORE: '⚪', UNKNOWN: '❔' }[verdict];

const where = a.namespace ? ` · \`${a.namespace}${a.pod ? '/' + a.pod : ''}\`` : '';
const head = `${emoji} **${verdict}** — \`${a.alertname}\`${where}`;
const rest = reply.replace(/^VERDICT:.*$/im, '').trim();

const message = [head, '```', rest, '```', a.runbook ? `<${a.runbook}>` : '']
  .filter(Boolean).join('\n').slice(0, 1900);

return { json: { message, verdict, raw: reply } };
